using DadoHome.Api.Data;using Microsoft.EntityFrameworkCore;
namespace DadoHome.Api.Inventory;
public record StockReturnRequest(Guid OrderItemId,int Quantity,string Reason,string IdempotencyKey);
public class ReturnService(DadoDbContext db){public async Task<(bool Ok,string? Error,ProductReturn? Return)> ReturnToStock(Guid orderId,StockReturnRequest r,string actorId){if(r.Quantity<=0||string.IsNullOrWhiteSpace(r.IdempotencyKey))return(false,"InvalidReturn",null);var existing=await db.ProductReturns.SingleOrDefaultAsync(x=>x.IdempotencyKey==r.IdempotencyKey);if(existing is not null)return(true,null,existing);await using var tx=await db.Database.BeginTransactionAsync(System.Data.IsolationLevel.Serializable);var item=await db.OrderItems.SingleOrDefaultAsync(x=>x.Id==r.OrderItemId&&x.OrderId==orderId);if(item is null)return(false,"OrderItemNotFound",null);if(item.ReturnedQuantity+r.Quantity>item.Quantity)return(false,"ReturnQuantityExceedsSold",null);var product=await db.Products.SingleOrDefaultAsync(x=>x.Id==item.ProductId);if(product is null)return(false,"ProductNotFound",null);item.ReturnedQuantity+=r.Quantity;product.Stock+=r.Quantity;var ret=new ProductReturn{Id=Guid.NewGuid(),OrderId=orderId,OrderItemId=item.Id,ProductId=product.Id,Quantity=r.Quantity,Reason=r.Reason.Trim(),IdempotencyKey=r.IdempotencyKey,ActorId=actorId};db.ProductReturns.Add(ret);db.AuditLogs.Add(new AuditLog{Id=Guid.NewGuid(),ActorId=actorId,Action="PRODUCT_RETURNED_STOCK_INCREMENTED",Entity="Order",EntityId=orderId.ToString()});await db.SaveChangesAsync();await tx.CommitAsync();return(true,null,ret);}}
